insert into public.herodle_hints (hero_id, emoji, palette, symbol, dominant, dossier) values
  ('iron-man', array['🏭', '💰', '🔧', '🦾', '🤖']::text[], array['#b11226', '#f9a825', '#90a4ae']::text[], 'reaktor', 'rdeča', array['Prvič se pojavi v 60. letih.', 'Nima nadnaravnih moči — vse si naredi sam.', 'Je izumitelj, milijarder in rad ima zabave.', 'V jami je moral iz odpadkov sestaviti prvi oklep.', 'Na prsih mu sveti majhen krožni reaktor.', 'Rdeče-zlat leteči oklep z repulzorji v dlaneh.']::text[]),
  ('captain-america', array['🪖', '💉', '🧊', '🛡️', '⭐']::text[], array['#1f4fa3', '#c62828', '#eceff1']::text[], 'zvezda', 'modra', array['Prvič se pojavi v 40. letih.', 'Bil je droben fant, ki so ga vojaki zavrnili.', 'Poskusni serum ga je naredil vrhunskega vojaka.', 'Desetletja je preživel zamrznjen v ledu.', 'Nosi okrogel ščit iz skoraj neuničljive kovine.', 'Modro obleko krasita bela zvezda in rdeče-bele proge.']::text[]),
  ('thor', array['🌈', '🍺', '🌩️', '⚡', '🔨']::text[], array['#b3262e', '#90a4ae', '#fdd835']::text[], 'kladivo', 'rdeča', array['Prvič se pojavi v 60. letih.', 'Ni z Zemlje, a jo ima rad.', 'Je sin vladarja nebeškega kraljestva.', 'Upravlja z gromom in strelami.', 'Njegovo orožje lahko dvigne le tisti, ki je vreden.', 'Dolgolasi bojevnik z rdečim plaščem in kladivom.']::text[]),
  ('hulk', array['🧪', '☢️', '😤', '💪', '🟢']::text[], array['#4caf50', '#6a1b9a', '#33691e']::text[], null, 'zelena', array['Prvič se pojavi v 60. letih.', 'Je izjemno pameten znanstvenik.', 'Po nesreči z žarki gama se je za vedno spremenil.', 'Ko se razjezi, postane velikan.', 'Bolj ko je jezen, močnejši je.', 'Ogromen zelen orjak v strganih vijoličnih hlačah.']::text[]),
  ('spider-man', array['🏙️', '📸', '🕸️', '👵', '🕷️']::text[], array['#d32f2f', '#1565c0', '#212121']::text[], 'pajek', 'rdeča', array['Prvič se pojavi v 60. letih.', 'Ne leti.', 'Ima teto, ki ga je vzgojila.', 'Je najstnik, ki fotografira za časopis.', 'Po stenah pleza, nevarnost čuti v tilniku.', 'Ugriz radioaktivnega pajka mu je dal moči.']::text[]),
  ('black-widow', array['🩰', '🪆', '🕵️‍♀️', '🔫', '🕷️']::text[], array['#262626', '#c62828', '#9e9e9e']::text[], 'peščena ura', 'črna', array['Prvič se pojavi v 60. letih.', 'Nima nadnaravnih moči.', 'Odraščala je v strogem tajnem programu.', 'Je vrhunska vohunka in mojstrica preobleke.', 'Na pasu nosi rdečo peščeno uro.', 'Rdečelasa ruska agentka v črni obleki.']::text[]),
  ('hawkeye', array['🎯', '🎪', '👂', '🏹', '🟣']::text[], array['#6a1b9a', '#212121', '#9e9e9e']::text[], 'tarča', 'vijolična', array['Prvič se pojavi v 60. letih.', 'Je navaden človek med bogovi in velikani.', 'Odraščal je v cirkusu.', 'Nikoli ne zgreši.', 'V tulu ima puščice s posebnimi konicami.', 'Lokostrelec v vijolični opravi.']::text[]),
  ('black-panther', array['👑', '🌍', '🌿', '💎', '🐆']::text[], array['#2b2b3a', '#9575cd', '#b0bec5']::text[], null, 'črna', array['Prvič se pojavi v 60. letih.', 'Je kralj.', 'Njegova dežela je skrita pred svetom.', 'Moč mu je dala posebna srčasta zel.', 'Obleka iz vibranija vpija udarce.', 'Kralj v črni obleki s kremplji, ki se imenuje po mački.']::text[]),
  ('doctor-strange', array['🏥', '🙌', '🏔️', '🧿', '🌀']::text[], array['#1e3a8a', '#c62828', '#fdd835']::text[], 'oko', 'modra', array['Prvič se pojavi v 60. letih.', 'Nekoč je bil zelo samozavesten zdravnik.', 'Po prometni nesreči so ga izdale roke.', 'Zdravilo je iskal v gorah na vzhodu.', 'Okoli vratu nosi amulet, ki upravlja s časom.', 'Čarovnik z rdečim plaščem, ki leti sam od sebe.']::text[]),
  ('scarlet-witch', array['🧬', '👯', '📺', '🔮', '👑']::text[], array['#c2185b', '#b71c1c', '#212121']::text[], null, 'roza', array['Prvič se pojavi v 60. letih.', 'Ima brata dvojčka.', 'Sprva je bila v nasprotnem taboru.', 'Lahko spremeni resničnost okoli sebe.', 'Ustvarila je celo mesto, kot iz televizijske nanizanke.', 'Rdeča čarovnica s krono na glavi.']::text[]),
  ('quicksilver', array['👯', '🏃', '💨', '⏱️', '⚡']::text[], array['#1e88e5', '#eceff1', '#90a4ae']::text[], 'strela', 'modra', array['Prvič se pojavi v 60. letih.', 'Ima sestro dvojčico.', 'Njegov oče je vladar magnetizma.', 'Je nestrpen in hitro se razjezi.', 'Teče hitreje od zvoka.', 'Srebrnolas tekač z modro opravo in strelo.']::text[]),
  ('vision', array['🧠', '🤖', '💛', '💎', '👻']::text[], array['#c62828', '#2e7d32', '#fdd835']::text[], 'kamen', 'rdeča', array['Prvič se pojavi v 60. letih.', 'Ni rojen, ampak ustvarjen.', 'Lahko gre skozi stene.', 'Zaljubljen je v čarovnico.', 'Na čelu ima rumen dragulj.', 'Rdečeobrazi android z zelenim in rumenim plaščem.']::text[]),
  ('ant-man', array['🔬', '🕵️', '👧', '🔽', '🐜']::text[], array['#b71c1c', '#212121', '#90a4ae']::text[], null, 'rdeča', array['Prvič se pojavi v 70. letih.', 'Bil je vlomilec, preden je postal junak.', 'Ima hčerko, ki jo ima zelo rad.', 'Obleka ga lahko pomanjša ali poveča.', 'Z žuželkami se pogovarja s posebno čelado.', 'Junak, ki je majhen kot mravlja.']::text[]),
  ('wasp', array['💃', '🔬', '🔽', '🪽', '🐝']::text[], array['#f9a825', '#212121', '#c62828']::text[], null, 'zlata', array['Prvič se pojavi v 60. letih.', 'Je modna oblikovalka in bogatašinja.', 'Bila je ena prvih članic slavne ekipe.', 'Lahko se pomanjša in leti.', 'Iz rok strelja pikajoče žarke.', 'Junakinja s krili kot žuželka in rumeno-črno obleko.']::text[]),
  ('captain-marvel', array['✈️', '👩‍✈️', '💥', '🐈', '⭐']::text[], array['#1565c0', '#c62828', '#fdd835']::text[], 'zvezda', 'modra', array['Prvič se pojavi v 60. letih.', 'Je pilotka letalskih sil.', 'Spomin so ji vzeli vesoljci.', 'Absorbira energijo in jo izstreli.', 'Ima mačko, ki v resnici ni mačka.', 'Modro-rdeča obleka z zlato zvezdo na prsih.']::text[]),
