  ('winter-soldier', array['🪖', '❄️', '🧠', '🦾', '⭐']::text[], array['#37474f', '#212121', '#c62828']::text[], 'rdeča zvezda', 'siva', array['Prvič se pojavi v 40. letih.', 'Bil je pomočnik slavnega vojaka.', 'Mislili so, da je padel v vojni.', 'Desetletja so mu prali spomin.', 'Ima kovinsko levo roko.', 'Plačanec z rdečo zvezdo na kovinski rami.']::text[]),
