  ('hercules', array['🏛️', '⚡', '🦁', '💪', '🪓']::text[], array['#f9a825', '#6d4c41', '#eceff1']::text[], null, 'zlata', array['Prvič se pojavi v 60. letih.', 'Je pol bog, pol človek.', 'Rad ima zabave in pretepe.', 'Opravil je dvanajst slovitih nalog.', 'Nosi kožo leva in velik bat.', 'Grški junak, sin vrhovnega boga Olimpa.']::text[]),
  ('she-hulk', array['⚖️', '👩‍💼', '🩸', '💪', '🟢']::text[], array['#4caf50', '#eceff1', '#6a1b9a']::text[], null, 'zelena', array['Prvič se pojavi v 80. letih.', 'Je odvetnica.', 'Moči je dobila s transfuzijo krvi sorodnika.', 'Rada se pogovarja z bralci in gledalci.', 'V velikanski obliki ostane pametna.', 'Zelena velikanka, sestrična jeznega orjaka.']::text[]),
