  ('shang-chi', array['🥋', '🚌', '🎤', '💍', '🐉']::text[], array['#c62828', '#fdd835', '#212121']::text[], null, 'rdeča', array['Prvič se pojavi v 70. letih.', 'Je mojster borilnih veščin.', 'Njegov oče vodi skrivno organizacijo.', 'V San Franciscu je parkiral avtomobile.', 'Nosi deset prstanov, ki so bili očetovi.', 'Kungfu junak, ki se bori ob zmaju.']::text[]),
  ('moon-knight', array['🏺', '💀', '🧠', '🌙', '🌕']::text[], array['#eceff1', '#9e9e9e', '#fdd835']::text[], 'polmesec', 'bela', array['Prvič se pojavi v 70. letih.', 'Bil je plačanec.', 'V njem živi več osebnosti.', 'Služi egipčanskemu bogu meseca.', 'Ponoči nosi bel plašč s kapuco.', 'Bel maščevalec s srebrnim polmesecem na prsih.']::text[]),
  ('black-bolt', array['👑', '🤫', '🐕', '🗣️', '💥']::text[], array['#212121', '#90caf9', '#fdd835']::text[], 'strela', 'črna', array['Prvič se pojavi v 60. letih.', 'Je kralj skrite rase.', 'Skoraj nikoli ne spregovori.', 'Ima velikanskega psa, ki se teleportira.', 'Šepet lahko poruši celo mesto.', 'Črnooblečen vladar z vilico na čelu.']::text[]),
