  ('yelena-belova', array['🪆', '🧥', '🐺', '🩰', '🕷️']::text[], array['#37474f', '#212121', '#c62828']::text[], null, 'siva', array['Prvič se pojavi v 90. letih.', 'Odraščala je v tajnem programu.', 'Ima »sestro«, ki je postala slavna junakinja.', 'Obožuje svoj jopič z veliko žepi.', 'Ima »očeta«, ki je bil sovjetski junak.', 'Druga »črna vdova«, mlajša sestra.']::text[]),
  ('red-guardian', array['🥶', '🪆', '🍔', '💪', '⭐']::text[], array['#c62828', '#fdd835', '#212121']::text[], 'zvezda', 'rdeča', array['Prvič se pojavi v 60. letih.', 'Je sovjetski odgovor na zvezdnatega junaka.', 'Rad pripoveduje o svoji slavni preteklosti.', 'Kostum mu je postal pretesen.', 'Je »oče« dveh vohunk.', 'Rdeči superjunak s srpom in kladivom.']::text[]),
  ('us-agent', array['🎖️', '💉', '😠', '🛡️', '⭐']::text[], array['#1a237e', '#c62828', '#eceff1']::text[], 'zvezda', 'modra', array['Prvič se pojavi v 80. letih.', 'Je vojak.', 'Vlada ga je izbrala za naslednika legende.', 'Vzel je serum, ki ga je naredil močnejšega.', 'Pred kamerami je storil nekaj groznega s ščitom.', 'Temnejša različica zvezdnatega junaka.']::text[]),
