  ('gamora', array['👭', '🗡️', '💚', '🌌', '🪐']::text[], array['#2e7d32', '#212121', '#9e9e9e']::text[], null, 'zelena', array['Prvič se pojavi v 70. letih.', 'Je posvojena hči.', 'Ima sestro, s katero se je nenehno pretepala.', 'Vzgojil jo je titan, ki je uničil njen svet.', 'Velja za najnevarnejšo žensko v galaksiji.', 'Zelena bojevnica z mečem, članica varuhov.']::text[]),
  ('rocket', array['🔫', '💣', '🧪', '😾', '🦝']::text[], array['#ef6c00', '#1565c0', '#212121']::text[], null, 'oranžna', array['Prvič se pojavi v 70. letih.', 'Je zelo majhen.', 'Rad krade in razstreljuje.', 'Na njem so delali poskuse.', 'Najboljši prijatelj je drevo.', 'Kosmat črnooki sesalec s puško večjo od sebe.']::text[]),
  ('groot', array['🌱', '🗣️', '🪴', '🦝', '🌳']::text[], array['#6d4c41', '#33691e', '#8d6e63']::text[], null, 'rjava', array['Prvič se pojavi v 60. letih.', 'Ni človek.', 'Ima zelo omejen besednjak.', 'Ko umre, lahko zraste znova.', 'Iz njega rastejo veje in cvetje.', 'Živo drevo, ki pove le tri besede.']::text[]),
